package android.app;import android.content.*;import android.widget.*;import android.view.View;import java.util.*;
public class AlertDialog extends Dialog {public CharSequence title,message;public CharSequence[] items;public int selected=-1;public boolean singleChoice;public DialogInterface.OnClickListener itemListener;public final Map<Integer,Button> buttons=new LinkedHashMap<>();public AlertDialog(Context c){super(c);}public Button getButton(int id){return buttons.get(id);}
public static class Builder {private final AlertDialog d;public Builder(Context c){d=new AlertDialog(c);}public Builder setTitle(CharSequence t){d.title=t;return this;}public Builder setMessage(CharSequence t){d.message=t;return this;}public Builder setCancelable(boolean b){d.setCancelable(b);return this;}public Builder setView(View v){d.setContentView(v);return this;}public Builder setItems(CharSequence[] a,DialogInterface.OnClickListener l){d.items=a;d.itemListener=l;return this;}public Builder setSingleChoiceItems(CharSequence[] a,int s,DialogInterface.OnClickListener l){setItems(a,l);d.selected=s;d.singleChoice=true;return this;}
private Builder button(int id,CharSequence t,DialogInterface.OnClickListener l){Button b=new Button(d.context);b.setText(t);b.setOnClickListener(v->{if(l!=null)l.onClick(d,id);d.dismiss();});d.buttons.put(id,b);return this;}
public Builder setPositiveButton(CharSequence t,DialogInterface.OnClickListener l){return button(-1,t,l);}public Builder setNegativeButton(CharSequence t,DialogInterface.OnClickListener l){return button(-2,t,l);}public Builder setNeutralButton(CharSequence t,DialogInterface.OnClickListener l){return button(-3,t,l);}public Builder setPositiveButton(int id,DialogInterface.OnClickListener l){return setPositiveButton(rv.batch.Platform.resource("android.string."+id,new Object[0]),l);}public Builder setNegativeButton(int id,DialogInterface.OnClickListener l){return setNegativeButton(rv.batch.Platform.resource("android.string."+id,new Object[0]),l);}public Builder setNeutralButton(int id,DialogInterface.OnClickListener l){return setNeutralButton(rv.batch.Platform.resource("android.string."+id,new Object[0]),l);}public AlertDialog show(){d.show();return d;}}}
